  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- New tests for Issue #1: Brick Bounce ---

// We need a way to trigger brick collision in tests.
// Since brick collision is currently inside frame(), we can't easily test it
// without mocking the canvas context.
// For now, I will implement the fix in neon.js and create a new test function
// for brick resolution that I will export from neon.js.

// Actually, I should first implement the fix in neon.js, but the instructions
