import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  resolveBrickCollision,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 500, r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// --- Issue #1: Brick Bounce Tests ---

test('resolveBrickCollision: bounce off top face', () => {
  const ball = { x: 100, y: 85, r: 10, vx: 0, vy: 100 }; // Approaching from top
  const brick = { x: 80, y: 90, w: 40, h: 20 };

  const hit = resolveBrickCollision(ball, brick);
  assert.equal(hit, true);
  assert.equal(ball.vy, -100, 'vy should be flipped');
  assert.equal(ball.y, 80, 'ball should be pushed out to y = brick.y - r');
});

test('resolveBrickCollision: bounce off bottom face', () => {
  const ball = { x: 100, y: 115, r: 10, vx: 0, vy: -100 }; // Approaching from bottom
  const brick = { x: 80, y: 90, w: 40, h: 20 };

  const hit = resolveBrickCollision(ball, brick);
  assert.equal(hit, true);
  assert.equal(ball.vy, 100, 'vy should be flipped');
  assert.equal(ball.y, 120, 'ball should be pushed out to y = brick.y + h + r');
});

test('resolveBrickCollision: bounce off left face', () => {
  const ball = { x: 75, y: 100, r: 10, vx: 100, vy: 0 }; // Approaching from left
  const brick = { x: 80, y: 90, w: 40, h: 20 };

  const hit = resolveBrickCollision(ball, brick);
  assert.equal(hit, true);
  assert.equal(ball.vx, -100, 'vx should be flipped');
  assert.equal(ball.x, 70, 'ball should be pushed out to x = brick.x - r');
});

test('resolveBrickCollision: bounce off right face', () => {
  const ball = { x: 130, y: 100, r: 10, vx: -100, vy: 0 }; // Approaching from right
  const brick = { x: 80, y: 90, w: 40, h: 20 };

  const hit = resolveBrickCollision(ball, brick);
  assert.equal(hit, true);
  assert.equal(ball.vx, 100, 'vx should be flipped');
  assert.equal(ball.x, 130, 'ball should be pushed out to x = brick.x + w + r'); // Wait, 120+10 = 130. Correct.
});

test('resolveBrickCollision: corner hit (diagonal bounce)', () => {
  // Construct a situation where overlapX == overlapY
  // Brick: (80, 90, 40, 20). Ball r=10.
  // Ball at (85, 95) -> OverlapX = (85+10) - 80 = 15, OverlapY = (85+10) - 90 = 5? No.
  // Let's be precise.
  const brick = { x: 80, y: 90, w: 40, h: 20 };
  const ball = { x: 75, y: 85, r: 10, vx: 100, vy: 100 };
  // OverlapX: ball.x + r - brick.x = 75 + 10 - 80 = 5
  // OverlapY: ball.x + r - brick.y = 85 + 10 - 90 = 5
  // Since overlapX == overlapY, it should trigger the corner case.

  const hit = resolveBrickCollision(ball, brick);
  assert.equal(hit, true);
  assert.equal(ball.vx, -100, 'vx should be flipped');
  assert.equal(ball.vy, -100, 'vy should be flipped');
});

